$1
    </script>

    <!-- 日记渲染目标容器 -->
    <div id="zxm-diary-output" class="max-w-3xl mx-auto"></div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {

            class DiaryRenderer {
                constructor(dataSourceId, outputContainerId) {
                    this.dataSourceId = dataSourceId;
                    this.outputContainerId = outputContainerId;
                    this.themes = ['night', 'blog', 'scholarly', 'fairy-tale'];
                    this.defaultTheme = 'fairy-tale';
                    this.diaryWrapper = null;
                    this.bodyBackground = document.getElementById('diary-body-background');
                }

                init() {
                    try {
                        const yamlDataSource = document.getElementById(this.dataSourceId);
                        if (!yamlDataSource) throw new Error(`Data source #${this.dataSourceId} not found.`);

                        const rawYaml = yamlDataSource.textContent.trim();
                        if (!rawYaml) return;

                        const data = jsyaml.load(rawYaml);
                        const diaryData = data['祝星梦的手记'];
                        const outputContainer = document.getElementById(this.outputContainerId);

                        if (!diaryData || !outputContainer) throw new Error('Invalid YAML data or output container not found.');

                        this.render(diaryData, outputContainer);
                        this.diaryWrapper = document.getElementById('diary-wrapper');
                        this.setupThemeSwitcher();

                    } catch (e) {
                        console.error('Error rendering diary:', e);
                        const outputContainer = document.getElementById(this.outputContainerId);
                        if (outputContainer) {
                            outputContainer.innerHTML = `<div class="text-red-500 text-center p-4 bg-red-900/20 rounded">手记数据加载失败: ${e.message}</div>`;
                        }
                    }
                }

                render(diaryData, container) {
                    const formattedContent = diaryData.内容
                        .split('\n')
                        .filter(p => p.trim() !== '')
                        .map(p => `<p>${p.trim()}</p>`)
                        .join('');

                    const fairyTaleRibbon = `<div class="ribbon"><i class="fa fa-star"></i></div>`;

                    container.innerHTML = `
                        <div id="diary-wrapper" class="diary-wrapper">
                            <details class="diary-container" open>
                                <summary class="diary-summary">
                                    <div class="flex items-center space-x-3">
                                        <i class="fa fa-book diary-icon"></i>
                                        <span class="font-bold text-lg diary-title">祝星梦的秘密手记</span>
                                    </div>
                                    <div class="flex items-center space-x-3">
                                        <div id="theme-switcher" class="theme-switcher-container">
                                            <button data-theme="night" class="theme-btn" title="夜间"><i class="fa fa-moon-o"></i></button>
                                            <button data-theme="blog" class="theme-btn" title="博客"><i class="fa fa-newspaper-o"></i></button>
                                            <button data-theme="scholarly" class="theme-btn" title="书卷"><i class="fa fa-paint-brush"></i></button>
                                            <button data-theme="fairy-tale" class="theme-btn" title="童话"><i class="fa fa-magic"></i></button>
                                        </div>
                                        <i class="fa fa-chevron-down diary-icon-chevron"></i>
                                    </div>
                                </summary>
                                <div class="diary-body">
                                    <div class="diary-body-content p-6">
                                        <header class="diary-header pb-4 mb-6 border-b flex justify-between items-center flex-wrap gap-y-2">
                                            <div class="font-bold diary-username">
                                                <i class="fa fa-user-circle-o mr-2"></i>${diaryData.用户名称}
                                            </div>
                                            <div class="flex items-center gap-x-3 flex-wrap diary-meta">
                                                <span class="diary-header-item">${diaryData.日期} ${diaryData.星期}</span>
                                                <span class="diary-header-item">${diaryData.时间}</span>
                                                <span class="diary-header-item">${diaryData.天气}</span>
                                            </div>
                                        </header>
                                        <article class="diary-content text-base">
                                            ${formattedContent}
                                        </article>
                                    </div>
                                </div>
                                ${fairyTaleRibbon}
                            </details>
                        </div>
                    `;
                }

                setupThemeSwitcher() {
                    const themeButtons = document.querySelectorAll('#theme-switcher .theme-btn');
                    const savedTheme = localStorage.getItem('zxm_diary_theme') || this.defaultTheme;

                    const switchToTheme = (theme) => {
                        this.themes.forEach(t => this.bodyBackground.classList.remove(`theme-${t}`));
                        this.bodyBackground.classList.add(`theme-${theme}`);

                        themeButtons.forEach(btn => {
                            btn.classList.toggle('active', btn.dataset.theme === theme);
                        });

                        localStorage.setItem('zxm_diary_theme', theme);
                    };

                    themeButtons.forEach(button => {
                        button.addEventListener('click', (e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            switchToTheme(button.dataset.theme);
                        });
                    });

                    switchToTheme(savedTheme);
                }
            }

            new DiaryRenderer('zxm-yaml-data', 'zxm-diary-output').init();
        });
    </script>
</body>
</html>
