      --font-family-override: var(--font-cute);
    }

    .theme-eye {
      --bg-main: #C7EDCC; /* Light Green */
      --bg-section: #F0FFF0; /* Honeydew */
      --text-main: #556B2F; /* DarkOliveGreen */
      --text-header: #2E8B57; /* SeaGreen */
      --border-color: #8FBC8F; /* DarkSeaGreen */
      --progress-bg: #E9F5E9;
      --coexistence-color: #6B8E23; /* OliveDrab */
      --zhiwei-color: #CD5C5C; /* IndianRed */
      --xingmeng-color: #3CB371; /* MediumSeaGreen */
      --accent-color: #8B4513; /* SaddleBrown */
      --font-family-override: var(--font-main);
    }

    .theme-night {
      --bg-main: #2C2F33;
      --bg-section: #23272A;
      --text-main: #DCDCDC;
      --text-header: #FFFFFF;
      --border-color: #4F545C;
      --progress-bg: #3A3E44;
      --coexistence-color: #7289DA; /* Discord Blue */
      --zhiwei-color: #F875AA; /* Pastel Pink */
      --xingmeng-color: #87CEEB; /* Sky Blue */
      --accent-color: #99AAB5;
      --font-family-override: var(--font-main);
    }

    /* --- BASE STRUCTURE --- */
    .card-container {
      display: flex;
      justify-content: center;
      align-items: center;
      font-family: var(--font-family-override, var(--font-main));
      padding: 20px;
    }

    .card-body {
      background-color: var(--bg-main);
      color: var(--text-main);
      border-radius: var(--border-radius-main);
      padding: 20px 25px;
      width: 100%;
      max-width: 450px;
      box-shadow: 0 8px 20px rgba(0, 0, 0, 0.15);
      border: 1px solid var(--border-color);
      transition: background-color var(--transition-speed), color var(--transition-speed), border-color var(--transition-speed);
    }

    /* --- DATE HEADER --- */
    .date-header {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      text-align: center;
      color: var(--text-header);
      margin-bottom: 20px;
      padding-bottom: 15px;
      border-bottom: 2px solid var(--border-color);
      font-weight: 700;
      transition: color var(--transition-speed), border-color var(--transition-speed);
    }

    .date-header .prefix, .date-header .suffix {
      font-size: 1.2em;
      flex: 1;
    }
    .date-header .prefix { text-align: left; }
    .date-header .suffix { text-align: right; }

    .date-header .day-number {
      font-size: 3.2em;
      line-height: 1;
      font-weight: 700;
      color: var(--accent-color);
      transition: color var(--transition-speed);
      flex-shrink: 0;
    }
    .theme-cute .date-header .day-number {
       text-shadow: 2px 2px 3px rgba(0,0,0,0.1);
    }

    /* --- SECTIONS --- */
    .section {
      background-color: var(--bg-section);
      border-radius: var(--border-radius-small);
      margin-bottom: 15px;
      padding: 15px;
      border: 1px solid var(--border-color);
      transition: background-color var(--transition-speed), border-color var(--transition-speed);
    }

    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      cursor: pointer;
      font-size: 1.3em;
      font-weight: 700;
      color: var(--text-header);
      transition: color var(--transition-speed);
      user-select: none;
    }
    .theme-cute .section-header { font-size: 1.5em; }

    .section-header .arrow {
      font-size: 0.8em;
      transition: transform var(--transition-speed);
    }
    .section-header.expanded .arrow {
      transform: rotate(90deg);
    }

    .section-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.4s ease-out, padding-top 0.4s ease-out;
      padding-top: 0;
    }

    .section-content.expanded {
      max-height: 200px; /* Adjust as needed */
      padding-top: 15px;
    }

    /* --- PROPERTY & PROGRESS BAR --- */
    .property-name {
      font-size: 1em;
      margin-bottom: 8px;
      display: flex;
      justify-content: space-between;
    }

    .progress-bar-container {
      background-color: var(--progress-bg);
      border-radius: 25px;
      height: 16px;
      width: 100%;
      overflow: hidden;
      border: 1px solid var(--border-color);
      transition: background-color var(--transition-speed), border-color var(--transition-speed);
    }

    .progress-bar-inner {
      height: 100%;
      border-radius: 25px;
      width: 0%; /* Set by JS */
      transition: width 0.5s ease-in-out, background-color var(--transition-speed);
    }

    .coexistence-bar { background-color: var(--coexistence-color); }
    .zhiwei-bar { background-color: var(--zhiwei-color); }
    .xingmeng-bar { background-color: var(--xingmeng-color); }

    /* --- THEME SWITCHER --- */
    .theme-switcher {
        display: flex;
        justify-content: center;
        align-items: center;
        margin-top: 20px;
        padding-top: 15px;
        border-top: 1px solid var(--border-color);
    }

    .theme-dot {
        width: 25px;
        height: 25px;
        border-radius: 50%;
        margin: 0 10px;
        cursor: pointer;
        border: 2px solid transparent;
        transition: transform 0.2s, border-color 0.2s;
    }
    .theme-dot:hover {
        transform: scale(1.15);
    }
    .theme-dot.active {
        border-color: var(--accent-color);
        transform: scale(1.2);
    }

    #dot-ink { background-color: #F5F5DC; border: 1px solid #A52A2A; }
    #dot-cute { background-color: #FFB6C1; border: 1px solid #FF69B4; }
    #dot-eye { background-color: #C7EDCC; border: 1px solid #556B2F; }
    #dot-night { background-color: #4F545C; border: 1px solid #DCDCDC; }

  </style>
</head>
