        <div class="theme-dot" id="dot-cute" data-theme="theme-cute"></div>
        <div class="theme-dot" id="dot-eye" data-theme="theme-eye"></div>
        <div class="theme-dot active" id="dot-night" data-theme="theme-night"></div>
      </div>

    </div>
  </div>

  <script type="module">
    function populateData() {
      const all_variables = getAllVariables();
      const default_val = '--';
      const max_val = 200;

      /* Helper to update a value and its progress bar */
      function updateStat(base_path, value_id, progress_id, max) {
        const value = _.get(all_variables, `stat_data.${base_path}`, null);

        if (value !== null) {
          $(`#${value_id}`).text(`${value} / ${max}`);
          const percentage = (value / max) * 100;
          $(`#${progress_id}`).css('width', `${percentage}%`);
        } else {
          $(`#${value_id}`).text(`${default_val} / ${max}`);
          $(`#${progress_id}`).css('width', '0%');
        }
      }

      /* World Date */
      const currentDate = _.get(all_variables, 'stat_data.世界.当前日期[0]', default_val);
      $('#world-current-date').text(currentDate);

      /* Coexistence Value */
      updateStat('关系.共存值[0]', 'relationship-coexistence-value', 'relationship-coexistence-progress', max_val);

      /* Jiang Zhiwei Anxiety */
      updateStat('江芷薇.安心值[0]', 'jiangzhiwei-anxiety-value', 'jiangzhiwei-anxiety-progress', max_val);

      /* Zhu Xingmeng Anxiety */
      updateStat('祝星梦.安心值[0]', 'zhuxingmeng-anxiety-value', 'zhuxingmeng-anxiety-progress', max_val);
    }

    function initCollapsible() {
      $('.section-header').on('click', function () {
        const $header = $(this);
        const $content = $header.next('.section-content');

        $header.toggleClass('expanded');
        $content.toggleClass('expanded');
      });
    }

    function initThemeSwitcher() {
      const $card = $('#status-card');
      const themes = ['theme-ink', 'theme-cute', 'theme-eye', 'theme-night'];

      $('.theme-dot').on('click', function() {
        const $dot = $(this);
        const theme = $dot.data('theme');

        /* Remove all theme classes and add the new one */
        $card.removeClass(themes.join(' ')).addClass(theme);

        /* Update active state for dots */
        $('.theme-dot').removeClass('active');
        $dot.addClass('active');
      });
    }

    function init() {
      populateData();
      initCollapsible();
      initThemeSwitcher();
    }

    $(() => {
      if (typeof errorCatched === 'function') {
        errorCatched(init)();
      } else {
        /* Fallback for environments where errorCatched is not defined */
        try {
          init();
        } catch (e) {
          console.error("Initialization failed:", e);
        }
      }
    });
  </script>
</body>
