                                    <header class="diary-header mb-6 pb-4 border-b text-sm flex justify-between items-center flex-wrap gap-2 theme-transition">
                                        <div>
                                            <span class="font-bold diary-username theme-transition">${diaryData.用户名称}</span>
                                        </div>
                                        <div class="flex items-center gap-4 diary-meta theme-transition">
                                            <span>${diaryData.日期}</span>
                                            <span>${diaryData.时间}</span>
                                            <span>${diaryData.天气}</span>
                                        </div>
                                    </header>
                                    <article class="diary-content text-lg leading-relaxed theme-transition">
                                        ${formattedContent}
                                    </article>
                                </div>
                            </details>
                        </div>
                    `;
                }

                setupThemeSwitcher() {
                    const wrapper = document.getElementById('diary-wrapper');
                    const themeButtons = document.querySelectorAll('#theme-switcher .theme-btn');

                    const savedTheme = localStorage.getItem('jzw_diary_theme') || 'night';

                    const switchToTheme = (theme) => {
                        this.themes.forEach(t => wrapper.classList.remove(`theme-${t}`));
                        wrapper.classList.add(`theme-${theme}`);

                        themeButtons.forEach(btn => {
                            btn.classList.toggle('active', btn.dataset.theme === theme);
                        });

                        localStorage.setItem('jzw_diary_theme', theme);
                    };

                    themeButtons.forEach(button => {
                        button.addEventListener('click', (e) => {
                            e.preventDefault(); // Prevent details from toggling
                            e.stopPropagation();
                            switchToTheme(button.dataset.theme);
                        });
                    });

                    // Apply initial theme
                    switchToTheme(savedTheme);
                }
            }
        </script>
    </body>
    </html>
