                    const data = jsyaml.load(rawYaml);
                    const chatData = data['祝星梦的聊天记录'];
                    const outputContainer = document.getElementById(this.outputContainerId);

                    if (!chatData || !outputContainer) throw new Error('Invalid YAML data or output container not found.');

                    this.render(chatData, outputContainer);
                    this.setupThemeSwitcher();

                } catch (e) {
                    console.error('Error rendering chat:', e);
                    const outputContainer = document.getElementById(this.outputContainerId);
                    if(outputContainer) {
                        outputContainer.innerHTML = `<div class="text-red-500 text-center p-4 bg-red-900/20 rounded">聊天记录加载失败: ${e.message}</div>`;
