            parseContent(content) {
                // Simple parser for [attachment.ext] syntax
                return content.replace(/\[(.*?\.(gif|png|jpg))\]/g, '<i class="attachment font-sans font-medium">$&</i>');
            }

            render(data, container) {
                const isOnline = data.在线状态.includes('在线');
                const statusClass = isOnline ? 'chat-status-online' : 'chat-status-offline';
                const statusIcon = isOnline ? '<i class="fa fa-circle text-xs mr-1"></i>' : '';
                const statusText = data.在线状态.includes(' ') ? data.在线状态.split(' ')[1] : data.在线状态;

