                            </div>
                        </summary>
                        <div class="chat-body p-4 border-t theme-transition">
                            ${messagesHtml}
                        </div>
                    </details>
                `;
            }

            setupThemeSwitcher() {
                const wrapper = document.getElementById('chat-wrapper');
                const themeButtons = document.querySelectorAll('#theme-switcher .theme-btn');

