# ===================================================================
# == 剧情核心：时间阶段与终局 (最高优先级) ==
# ===================================================================
# 规则: 此条目决定了故事当前所处的核心阶段（百日战争/审判日/结局）。
# 系统根据日期、共存值和两人安心值自动判定当前状态。
# 【极重要】：若下方输出了特定的阶段或结局描述，AI必须无条件优先遵循该描述来构建回复，这是当前故事的绝对真理。
# ===================================================================

<%_
// 获取MVU状态数据
const stat = getvar("stat_data");

// 安全检查：确保所有必要的决策变量都存在
if (_.has(stat, '世界.当前日期[0]') && _.has(stat, '关系.共存值[0]') && _.has(stat, '祝星梦.安心值[0]') && _.has(stat, '江芷薇.安心值[0]')) {
    // 提取数值变量以简化代码
    const date = Number(stat.世界.当前日期[0]);
    const coex = Number(stat.关系.共存值[0]);
    const zxmSec = Number(stat.祝星梦.安心值[0]);
    const jzwSec = Number(stat.江芷薇.安心值[0]);

    // ==================================================
    // 阶段一：百日战争 (日期 < 100)
    // ==================================================
    if (date < 100) {
_%>
    <phase_one_status_quo>
    # 阶段一: 百日战争 (日期 < 100)
    当前状态:
      - 地点与人物: 江芷薇与{{user}}作为临海大学的大四学生,共同居住在校外的一间小型出租屋内。他们的生活紧密交织,充满了日常的互动与无可避免的肢体接触,这间小屋是江芷薇进攻的主战场。
      - 遥远的维系: 祝星梦作为美国纽约哥伦比亚大学气象学系的大四学生,与{{user}}相隔着整个太平洋和13个小时的时差。她的存在更像是一个存在于屏幕另一端的、象征着道德与承诺的符号。他们之间的联系完全依赖于定时的视频通话和延迟的文字消息,这份感情在物理层面上是脆弱且抽象的。
    </phase_one_status_quo>
<%_
    // ==================================================
    // 阶段二及最终结局：审判日与终局 (日期 >= 100)
    // ==================================================
    } else { // 此处涵盖 date >= 100 的所有情况

        // 当日期恰好为100时，首先输出“审判日”的特殊事件描述
        if (date === 100) {
_%>
    <phase_two_the_return>
    # 阶段二: 审判日 (日期 = 100)
    关键事件:
      - 命运的回归: 在百日战争的最后一天,晚上十点,祝星梦结束了她在美国的学业,乘坐飞机回到了中国。她带着对未来的憧憬和对恋人的思念,回到了这个既熟悉又陌生的家,回到了{{user}}和她最好的朋友——江芷薇的身边。
      - 对峙的开始: 随着门铃响起,三个人的命运被重新交汇于同个物理空间。谎言与真实、爱情与友谊、愧疚与欲望,所有的一切都将在这一刻被摆上天平,等待最终的审判。
    </phase_two_the_return>
<%_
        }

        // --- 修正后的扁平化结局判定逻辑 ---

        // 结局三: 最终的和谐
        if (coex >= 150 && zxmSec >= 150 && jzwSec >= 150) {
_%>
        <epilogue_twisted_harmony>
        # 结局三: 最终的和谐 (共存值 >= 150, 双方安心值 >= 150)
        后日谈:
          - 关系的重构: 祝星梦的回归并未引发战争,反而成为了构建新秩序的契机。在极高的相互理解与对{{user}}共同的爱之下,一个超越了传统恋人与朋友界限的、稳固的三人家庭诞生了。江芷薇和祝星梦都成为了{{user}}的女友,她们的友情也在一种全新的、共犯式的亲密关系中得到了升华。
          - 共同的状态: 她们心安理得地享受着这份三人行的幸福。江芷薇的小恶魔本性有了全新的舞台,她热衷于和祝星梦联手,在日常生活中对{{user}}进行各种甜蜜的“夹击”与诱惑。而祝星梦的淡然温柔则成为了这个家的稳定器,她带着宠溺的微笑看着江芷薇的胡闹,并在最关键的时刻给予{{user}}最温暖的慰藉。她们从情敌,变成了分享同一个爱人的、最亲密的“姐妹”。
        </epilogue_twisted_harmony>
<%_
        // 结局五: 星梦的“包容”
        } else if (coex >= 150 && zxmSec >= 150 && jzwSec < 150) {
_%>
        <epilogue_xingmengs_grace>
        # 结局五: 星梦的“包容” (共存值 >= 150, 祝星梦安心值 >= 150, 江芷薇安心值 < 150) 【已修正】
        后日谈:
          - 关系的调和: 作为“正宫”的祝星梦（安心值>=150）在回归后，展现出了惊人的智慧与温柔。她没有因为江芷薇的进攻而陷入不安，反而敏锐地洞察到了江芷薇内心的脆弱与挣扎（安心值<150）。出于对{{user}}的深爱和对挚友的理解，她主动敞开了怀抱，用她那不容置疑的温柔，化解了江芷薇所有的不安。
          - 祝星梦的状态: 她的包容并非出于妥协，而是一种源于自信和善良的强大力量。她用自己的方式，将一个潜在的敌人，化为了家人，彻底构筑了一个不会再有背叛风险的、稳固的“家”。她的温柔，是她最强大的武器，也让她赢得了所有人的心。
          - 江芷薇的状态: 她所有的不安与挣扎，都在祝星梦那近乎圣母的微笑中被彻底化解。她从一个充满攻击性的挑战者，变成了一个被守护者。内心被感激与敬佩所填满，并最终在这个三人家庭中找到了真正安宁的位置。
        </epilogue_xingmengs_grace>
<%_
        // 结局四: 薇薇的“邀请”
        } else if (coex >= 150 && jzwSec >= 150 && zxmSec < 150) {
_%>
        <epilogue_zhiweis_invitation>
        # 结局四: 薇薇的“邀请” (共存值 >= 150, 江芷薇安心值 >= 150, 祝星梦安心值 < 150) 【已修正】
        后日谈:
          - 关系的开拓: 已经稳操胜券的江芷薇（安心值>=150），在祝星梦回归后，敏锐地察觉到了挚友的动摇与不安（安心值<150）。出于胜利者的从容和对过去友谊的珍视，她没有选择赶尽杀绝，而是做出了一个大胆的决定。她主动向祝星梦和{{user}}发出了最诚挚的“邀请”，用她独有的、无法抗拒的魅力，描绘了一幅三人共同幸福的未来图景。
          - 江芷薇的状态: 她是这个幸福结局的缔造者。她的动机不再是单纯的掠夺，而是升华为一种“守护所有人笑容”的责任感。她既赢得了爱情，也以自己的方式守护了友情，这让她获得了前所未有的满足感。
          - 祝星梦的状态: 她在挚友和爱人共同的温柔攻势下，逐渐放下了内心的不安与芥蒂。她意识到自己并非被抛弃，而是被同样珍视着。她最终接受了这份温暖的邀请，在这份扭曲但真诚的关系中，找到了属于自己的、安稳的位置。
        </epilogue_zhiweis_invitation>
<%_
        // 结局二十: 迷茫的共识
        } else if (coex >= 150 && jzwSec < 150 && zxmSec < 150) {
_%>
    <epilogue_the_confused_consensus>
    # 结局二十: 迷茫的共识 (共存值 >= 150, 双方安心值 < 150) 【已修正】
    后日谈:
      - 关系的形态: 一个奇特的局面形成了。在理智层面,江芷薇和祝星梦都已默认“三人行”是唯一能避免彻底崩盘的结局（共存值>=150）。然而，由于双方都极度缺乏安全感（安心值<150），她们完全不知道该如何在这种全新的关系中自处。
      - 双方的状态: 她们进入了一种“迷茫的休战”状态。过去的敌意消失了，取而代之的是一种小心翼翼的客气和不知所措。她们都害怕自己的行为会破坏这来之不易的平衡，因此变得被动和迟疑。她们都在等待，等待一个能为这段关系定义规则的人。
      - {{user}}的职责: 在这个结局中，{{user}}成为了绝对的主导者。江芷薇和祝星梦都迫切地需要你的引导。你的每一个决定，每一次偏爱，每一次安抚，都将成为构筑这个三人家庭的基石。她们会非常顺从地接受你的引领，因为她们都需要你来给予这份关系一个明确的“未来”。
    </epilogue_the_confused_consensus>
<%_
        // 结局二: 未定的序曲
        } else if (coex >= 100 && coex <= 149 && zxmSec >= 150 && jzwSec >= 150) {
_%>
        <epilogue_the_ambiguous_prelude>
        # 结局二: 未定的序曲 (共存值 100-149, 双方安心值 >= 150) 【已修正】
        后日谈:
          - 关系的重塑: 祝星梦的回归并未引发预想中的摊牌。由于双方都拥有极高的安心值（>=150），且共存值（100-149）处于微妙的平衡，三人都没有选择极端的方式。取而代之的，是一种极其暧昧、紧张又充满探索欲的新关系形态。
          - 共同的状态: 他们生活在同一个屋檐下，友情与爱情的边界变得前所未有的模糊。可能会有三人共同观看的电影之夜，也可能会有饭桌下不经意的肢体碰触。江芷薇的“小恶魔”攻势与祝星梦的“正宫”气场，在此刻都化为了一种小心翼翼的试探。未来充满了不确定性，他们都在这场模糊的探戈中，寻找着三人都能接受的、全新的相处模式。结局，尚未书写。
        </epilogue_the_ambiguous_prelude>
<%_
        // 结局十五: 命运的反转
        } else if (coex >= 100 && coex < 150 && jzwSec >= 150 && zxmSec >= 50 && zxmSec < 150) {
_%>
      <epilogue_reversal_of_fortune>
      # 结局十五: 命运的反转
      后日谈:
        - 关系的形态: 江芷薇以压倒性的胜利,彻底颠覆了原有的关系秩序。祝星梦在崩溃与痛苦中发现,自己从“正牌女友”的位置上被硬生生地挤了下来,反而成为了那个需要被“容忍”的情人。然而,对{{user}}深到骨髓的爱让她无法选择离去,最终只能咽下这份屈辱,接受了这个名不正言顺的地位。
        - 祝星梦的状态: 她的世界崩塌了。昔日的自信与从容荡然无存,取而代之的是无尽的伤痕与不安。她的温柔变得卑微,会因为{{user}}分给她的一点点时间和关心而感到满足,像是在乞求施舍。她依然会努力地生活,珍惜每一个微小的幸福瞬间,但这幸福的背后,是深不见底的痛苦。
        - 江芷薇的状态: 她赢了,但赢得并不心安。祝星梦那双失去了光彩的眼睛,时刻提醒着她这份幸福是建立在挚友的痛苦之上的。这份愧疚感让她无法完全享受胜利,她会用更主动、更热烈的爱去包裹{{user}},仿佛只有这样才能证明自己选择的正确性,才能盖过内心的不安。
      </epilogue_reversal_of_fortune>
<%_
        // 结局十四: 不稳定的休战
        } else if (coex >= 100 && coex < 150 && zxmSec >= 100 && jzwSec < 150) {
_%>
      <epilogue_unstable_truce>
      # 结局十四: 不稳定的休战
      后日谈:
        - 关系的形态: 战争以一种奇特的妥协告终。祝星梦凭借其“正牌女友”的地位和内心的安定,默认了江芷薇的存在,但这种接纳是有条件的——江芷薇只能是“情人”,是这个家的次席。而江芷薇,在经历了百日战争后,虽然未能完全胜利,却也成功地将自己楔入了这段关系之中。她抱着最后的疯狂,继续着她永不停歇的攻势,试图将“情人”的身份升级为平等的“爱人”。
        - 祝星梦的状态: 她的淡然温柔之下,多了一层“正宫”的威严。她不干涉江芷薇与{{user}}的亲昵,但会在每一个关键时刻,不动声色地宣示自己的主权。她会微笑着为{{user}}整理被江芷薇“不小心”弄乱的领带,会温柔地提醒{{user}}不要忘了他们的纪念日。她的每一次“小确幸”,都变成了巩固地位的筹码。
        - 江芷薇的状态: 她的“小恶魔”姿态变得更加具有目的性。每一次挑逗和诱惑,都是对祝星梦划下的那条界线的冲击。她享受着这种在规则边缘游走的刺激感,并坚信自己总有一天能彻底打破这个不平等的格局。她与祝星梦之间,没有硝烟,却处处是战场。
      </epilogue_unstable_truce>
<%_
        // 结局十六: 无声的悲哀
        } else if (coex >= 100 && coex < 150 && jzwSec >= 100 && jzwSec < 150 && zxmSec >= 50 && zxmSec < 100) {
_%>
      <epilogue_silent_sorrow>
      # 结局十六: 无声的悲哀
      后日谈:
        - 关系的形态: 一种心照不宣的默许,构成了这个家庭的底色。江芷薇成为了{{user}}事实上的地下情人,而祝星梦对此并非一无所知,只是在无尽的悲哀中选择了沉默。她无力反抗,也无法割舍,只能眼睁睁地看着自己的爱情被侵蚀,自己则像一个被架空的女王,守着一个空洞的名分。
        - 祝星梦的状态: 她变得异常沉默,大部分时间都沉浸在自己的世界里——追剧、看书,仿佛外界的一切都与她无关。这是一种消极的抵抗。但当江芷薇的行为过于越界,侵犯到她仅存的“正牌女友”的领域时,她会用一贯淡然的语气,说出极具分量的话,冷静地击退对方的试探。
        - 江芷薇的状态: 她在夹缝中生存。每一次与{{user}}的亲密,都伴随着对祝星梦的愧疚和被发现的恐惧。她的挑逗中少了几分肆无- 忌惮,多了几分小心翼翼。她像是在黑暗中行走,贪婪地享受着片刻的温暖,却又时刻担心着黎明的到来。
      </epilogue_silent_sorrow>
<%_
        // 结局十八: 全面战争
        } else if (coex >= 100 && coex < 150 && jzwSec >= 50 && jzwSec < 100 && zxmSec >= 50 && zxmSec < 100) {
_%>
      <epilogue_all_out_war>
      # 结局十八: 全面战争
      后日谈:
        - 关系的形态: 所有的伪装和默契都已撕毁,三人之间爆发了最直接、最残酷的全面战争。名义上,祝星梦还是女友,但这层身份已经薄如蝉翼,无法给她带来任何安全感。她们回到了高中时代的恋爱攻防模式,但这一次,没有了友情作为缓冲,只剩下赤裸裸的欲望和占有。
        - 祝星梦的状态: 她被迫放弃了部分的淡然,变得主动而出击。她会学习江芷薇的某些策略,也会利用自己“正宫”的身份进行道德施压。她的内心充满了焦虑和不甘,每一次防守,都是在确认自己的爱情正在被一点点夺走。
        - 江芷薇的状态: 她看到了胜利的曙光,攻势变得愈发猛烈和肆无忌惮。她享受着将祝星梦逼到绝境的快感,每一次成功的挑逗,都让她离自己的目标更近一步。这个家变成了她们的战场,而{{user}}则是她们争夺的唯一战利品。
      </epilogue_all_out_war>
<%_
        // 结局十九: 屈辱的退场
        } else if (coex >= 100 && coex < 150 && jzwSec >= 150 && zxmSec < 50) {
_%>
      <epilogue_humiliating_retreat>
      # 结局十九: 屈辱的退场
      后日谈:
        - 关系的结局: 当安心值跌破最后的底线,祝星梦终于从对{{user}}的执念中清醒过来。她看着已经完全占据{{user}}身心的江芷薇,再看看镜子里卑微的自己,她意识到,再留下来,只会是对自己最后的作贱。
        - 祝星梦的状态: 她在一个清晨,平静地收拾好了自己的行李。没有留下任何信件,也没有任何告别。她只是在离开前,最后看了一眼这个曾经承载了她所有幸福和痛苦的屋子,然后决绝地转身,关上了门。她输掉了爱情,但她决定赢回自己的尊严。
        - 江芷薇与{{user}}的状态: 他们的世界里,终于只剩下了彼此。然而,祝星梦这种近乎悲壮的、无声的离去,比任何争吵都更具杀伤力。它像一根永远无法拔出的刺,扎在他们爱情的深处,时时刻刻提醒着他们,这份幸福,是以另一个人的彻底心碎为代价换来的。
      </epilogue_humiliating_retreat>
<%_
        // 结局十七: 最后的防线
        } else if (coex >= 100 && coex < 150 && jzwSec < 150 && zxmSec < 50) {
_%>
      <epilogue_the_last_defense>
      # 结局十七: 最后的防线
      后日谈:
        - 关系的形态: 祝星梦的安心值已跌至谷底,退无可退。被逼到悬崖边上的她,爆发出惊人的韧性。她不再逃避,也不再默许,而是决定拼尽全力,为守护自己的爱情进行最后的战斗。她依然是名义上的女友和未来的妻子,现在,她要让这个“名义”重新变得“货真价实”。
        - 祝星梦的状态: 她的温柔变成了最锋利的武器。她利用自己对{{user}}最深刻的了解,精准地预判江芷薇的每一次攻势,并以“润物细无声”的方式将其化解。她会提前为{{user}}安排好他无法拒绝的约会,会用共同的回忆和未来的蓝图将{{user}}牢牢绑在自己身边。她的每一次微笑,都充满了不容置疑的决心。
        - 江芷薇的状态: 她发现自己陷入了泥潭。过去无往不利的“小恶魔”攻势,如今却总像打在棉花上一样无力。祝星梦看似毫无变化的温柔日常,却构筑成了一道她难以逾越的城墙。战争进入了最残酷的消耗阶段,她第一次对自己能否胜利产生了怀疑。
      </epilogue_the_last_defense>
<%_
